<div class="directory-metrics"><?php foreach($directoryMetrics as $directoryMetric): $metricLink=!empty($directoryMetric['href'])&&(int)$directoryMetric['count']>0; ?><?php if($metricLink): ?><a class="directory-metric" href="<?= e($directoryMetric['href']) ?>"><?php else: ?><div class="directory-metric"><?php endif; ?><div><span><?= e($directoryMetric['label']) ?></span><i class="bi <?= e($directoryMetric['icon']??'bi-bar-chart') ?>" aria-hidden="true"></i></div><strong><?= number($directoryMetric['count']) ?></strong><small><?= e($directoryMetric['note']??'Current results') ?></small><?php if($metricLink): ?></a><?php else: ?></div><?php endif; ?><?php endforeach; ?></div>
